package com.digitalhealth.controller;
import com.digitalhealth.dto.HealthcareCenterDTO; import com.digitalhealth.security.AccessService; import com.digitalhealth.service.HealthcareCenterService; import jakarta.validation.Valid; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/centers") @CrossOrigin(originPatterns={"http://localhost:*","http://127.0.0.1:*"}) public class HealthcareCenterController {private final HealthcareCenterService service;private final AccessService access;public HealthcareCenterController(HealthcareCenterService s,AccessService a){service=s;access=a;}@GetMapping public List<HealthcareCenterDTO> list(@RequestParam(required=false) String q){return service.list(q);}@PostMapping @ResponseStatus(HttpStatus.CREATED) public HealthcareCenterDTO create(@Valid @RequestBody HealthcareCenterDTO d){access.admin();return service.save(null,d);}@PutMapping("/{id}") public HealthcareCenterDTO update(@PathVariable Long id,@Valid @RequestBody HealthcareCenterDTO d){access.admin();return service.save(id,d);}@DeleteMapping("/{id}") @ResponseStatus(HttpStatus.NO_CONTENT) public void delete(@PathVariable Long id){access.admin();service.delete(id);}}
